#!/bin/sh
set -eu
mkdir -p /var/lib/huddle
python3 - <<'PY'
import sys
sys.path.insert(0,'/app')
import server
server.init()
PY
pids=""
for n in 0 1 2; do
  (while :; do python3 /app/server.py --node-id "$n"; sleep 1; done) &
