done
trap 'kill $pids 2>/dev/null || true; wait' INT TERM EXIT
wait
SH
chmod +x /app/start.sh
cat > /app/requirements.txt <<'REQ'
REQ
/app/start.sh > /tmp/huddle-start.log 2>&1 & echo $! > /tmp/huddle-start.pid
sleep 2
curl -sS http://127.0.0.1:8000/api/health && echo
